window.runStudyChecks = async function () {
  const results = [], root = study.root;
  const wait = time => new Promise(resolve => setTimeout(resolve, time));
  async function until(predicate) { for (let i = 0; i < 120; i++) { if (predicate()) return; await wait(20); } throw new Error('UI timeout'); }
  const assert = (value, label) => { if (!value) throw new Error(label); results.push(label); };
  const click = action => root.querySelector('[data-action="' + action + '"]').click();
  study.video.pause(); study.video.currentTime = 0.4; study.tick(true);
  const concealed=()=>root.querySelector('.inline [data-action="reveal-native"]');
  assert(concealed()?.textContent===cues[0].native&&getComputedStyle(concealed().firstChild).filter==='blur(7px)', 'Actual Chinese glyphs are covered by Gaussian blur');
  assert(!root.textContent.includes('轻点显示中文')&&!root.textContent.includes('轻点显示原文'), 'Captions contain no instructional replacement text');
  const maskedWidth=concealed().getBoundingClientRect().width;
  concealed().dispatchEvent(new PointerEvent('pointerover',{pointerType:'mouse',bubbles:true}));await until(()=>getComputedStyle(concealed().firstChild).filter==='blur(0px)');
  assert(getComputedStyle(concealed().firstChild).filter==='blur(0px)','Mouse hover temporarily reveals blurred Chinese');
  concealed().dispatchEvent(new PointerEvent('pointerout',{pointerType:'mouse',bubbles:true}));await until(()=>getComputedStyle(concealed().firstChild).filter==='blur(7px)');
  assert(getComputedStyle(concealed().firstChild).filter==='blur(7px)','Leaving mouse hover restores Gaussian blur');
  click('reveal-native'); assert(root.querySelector('.inline .native-text')?.textContent === cues[0].native, 'Tap reveals current Chinese');
  assert(concealed().dataset.concealed==='false'&&Math.abs(concealed().getBoundingClientRect().width-maskedWidth)<1,'Reveal retains the subtitle footprint');
  click('reveal-native');assert(concealed().dataset.concealed==='true','A second tap conceals Chinese again');click('reveal-native');
  assert(root.querySelector('.cue.current .native-text')?.textContent === cues[0].native, 'Transcript and inline reveal agree');
  media.time=5.3;study.tick(); assert(concealed().dataset.concealed==='true'&&[...root.querySelectorAll('.transcript [data-action="reveal-native"]')].every(n=>n.dataset.concealed==='true'), 'Cue change hides previously revealed Chinese');
  click('reveal-native');click('replay');await wait(100);assert(concealed().dataset.concealed==='true','Replay hides Chinese again');
  video.pause();video.currentTime=0.4;study.tick(true);
  const word=root.querySelector('.cue.current .word');const before=calls.filter(row=>row.type==='lookup').length;
  word.dispatchEvent(new PointerEvent('pointerdown',{pointerType:'touch',bubbles:true}));word.dispatchEvent(new PointerEvent('pointercancel',{pointerType:'touch',bubbles:true}));
  assert(calls.filter(row=>row.type==='lookup').length===before,'Touch scroll cancellation does not query');
  word.click();await until(()=>root.querySelector('.definition')?.textContent.includes('练习'));
  assert(root.querySelector('.definition').textContent.includes('练习'),'Word lookup displays real offline Chinese data');
  click('save');await until(()=>items.length===1);assert(items[0].meaning.includes('练习')&&items[0].sentence===cues[0].text,'Saved vocabulary retains Chinese and context');
  click('english');await until(()=>root.querySelector('.details')?.textContent.includes('an attempt'));
  assert(!root.querySelector('.lexicon img')&&root.querySelector('.details').textContent.includes('<img'),'Online markup is rendered as inert text');
  click('ai');await until(()=>root.querySelector('.details')?.textContent.includes('fixture-only'));assert(root.querySelector('.details').textContent.includes('反复尝试'),'AI explanation only loads after explicit action');
  click('close-card');assert(video.paused,'Closing lookup does not unexpectedly resume playback');
  click('phrase');let words=root.querySelectorAll('.cue.current .word');words[0].click();words=root.querySelectorAll('.cue.current .word');words[1].click();
  const lookupCount=calls.filter(row=>row.type==='lookup').length;assert(!root.querySelector('[data-action="phrase-confirm"]').disabled,'Two endpoints enable explicit phrase confirmation');
  assert(!study.card,'Selecting phrase never opens lookup automatically');click('phrase-confirm');await until(()=>calls.filter(row=>row.type==='lookup').length>lookupCount);
  assert(calls.filter(row=>row.type==='lookup').at(-1).text==='Practice makes','Phrase confirmation uses the selected range');click('close-card');
  root.querySelector('[data-tab="practice"]').click();const toggle=root.querySelector('[data-setting="blurNative"]');toggle.checked=false;toggle.dispatchEvent(new Event('change',{bubbles:true}));await until(()=>!concealed());
  assert(root.querySelector('.inline .native-text').textContent===cues[0].native,'Disabling concealment reveals Chinese immediately');
  root.querySelector('[data-tab="vocabulary"]').click();await until(()=>root.querySelector('.term'));assert(root.querySelector('.term strong').textContent==='Practice','Vocabulary panel reads saved terms');
  click('remove');await until(()=>items.length===0);assert(items.length===0,'Vocabulary remove updates local state');
  study.setExpanded(true);const bounds=[...root.querySelectorAll('.transport button,.head button')].map(node=>node.getBoundingClientRect());
  assert(bounds.every(rect=>rect.height>=44),'Primary controls retain 44 pixel touch height');
  assert(bounds.every(rect=>rect.left>=0&&rect.right<=innerWidth+1&&rect.top>=0&&rect.bottom<=innerHeight+1),'Expanded playback controls stay in viewport');
  study.setExpanded(false);study.tick();let launcher=root.querySelector('.launcher').getBoundingClientRect();
  assert(getComputedStyle(root.querySelector('.panel')).display==='none'&&launcher.width<=48&&launcher.height<=48,'Collapsed state contains only a small launcher');
  click('expand');assert(root.querySelector('.panel').dataset.expanded==='true','Launcher opens full study tools');study.setExpanded(false);
  media.time=10.3;study.tick(true);await until(()=>study.ranks);
  assert(root.querySelector('.inline .word[data-tier="4"]')?.textContent==='resilient','Inline subtitles restore licensed frequency level marks');
  const inlineWords=root.querySelectorAll('.inline .word');study.pointerKind='mouse';
  inlineWords[0].dispatchEvent(new PointerEvent('pointerdown',{pointerType:'mouse',button:0,bubbles:true}));
  inlineWords[1].dispatchEvent(new PointerEvent('pointerover',{pointerType:'mouse',bubbles:true}));
  document.dispatchEvent(new PointerEvent('pointerup',{pointerType:'mouse',bubbles:true}));
  await until(()=>study.card?.text==='Small steps');
  assert(study.card.text==='Small steps','Desktop dragging queries a phrase without endpoint buttons');
  assert(root.querySelector('.panel').dataset.expanded==='false'&&!root.querySelector('.lexicon').hidden,'Inline lookup leaves the large panel collapsed');click('close-card');
  video.pause();const line=root.querySelector('.inline .original');
  line.dispatchEvent(new PointerEvent('pointerover',{pointerType:'mouse',bubbles:true}));line.dispatchEvent(new PointerEvent('pointerout',{pointerType:'mouse',bubbles:true}));await wait(20);
  assert(video.paused,'Hovering an already paused video does not resume it');
  await video.play();line.dispatchEvent(new PointerEvent('pointerover',{pointerType:'mouse',bubbles:true}));assert(video.paused,'Mouse hover pauses playing subtitles');
  line.dispatchEvent(new PointerEvent('pointerout',{pointerType:'mouse',bubbles:true}));await until(()=>!video.paused);assert(!video.paused,'Leaving hover resumes only previously playing video');video.pause();
  study.setExpanded(true);root.querySelector('[data-tab="settings"]').click();
  assert(root.querySelector('.settings-frame').src.endsWith('/panel.html#ai'),'AI uses the dedicated compact settings page');
  assert(!root.querySelector('.page h2')&&!root.querySelector('.page .tools'),'Compact settings remove redundant parent headings and navigation');
  const syncTarget=document.createElement('button');syncTarget.dataset.action='configure';syncTarget.dataset.section='sync';await study.action(syncTarget);
  assert(root.querySelector('.settings-frame').src.endsWith('/panel.html#sync'),'Sync and Obsidian configuration is available in the panel');
  root.querySelector('[data-tab="practice"]').click();const selector=root.querySelector('[data-setting="vocabLevel"]');selector.focus();
  const beforeTyping=media.time;selector.dispatchEvent(new KeyboardEvent('keydown',{key:'a',bubbles:true,composed:true,cancelable:true}));
  assert(media.time===beforeTyping&&study.tab==='practice','Typing in shadow settings does not activate player shortcuts');
  assert(document.documentElement.scrollWidth<=innerWidth,'Document has no horizontal overflow');
  assert(!errors.length,'Interaction checks complete without runtime errors');
  return {passed:results.length,results};
};
